def f(n):
    return n // 10 + 3 * (n % 10)

# Find all cycles for n < 100.
all_cycles = []
seen_in_cycle = set()
for i in range(100):
    if i in seen_in_cycle:
        continue
    path = []
    curr = i
    while curr not in path:
        path.append(curr)
        curr = f(curr)

    # Found a cycle
    cycle_start_idx = path.index(curr)
    cycle = path[cycle_start_idx:]
    if cycle not in all_cycles:
        all_cycles.append(cycle)
        for x in cycle:
            seen_in_cycle.add(x)
    else:
        # This cycle was already found
        pass

print(f"All cycles for n < 100: {all_cycles}")
